) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Déchargement des données de la table `document`
--

INSERT INTO `document` (`id`, `title`, `abstract`, `file`, `created_at`, `updated_at`, `user_id`, `category_id`, `original_name`, `mime_type`) VALUES
(1, 'Oracle 11g - Administration de bases de données', 'L\'administration Oracle 11g consiste à installer, configurer, sécuriser et maintenir une instance de base de données pour garantir sa disponibilité et ses performances.  Les tâches critiques incluent la gestion du stockage (tablespaces), la sauvegarde et restauration via RMAN, et la surveillance active avec Oracle Enterprise Manager.', 'oracle-11g-administration-6a414ce7570df.pdf', '2026-06-28 18:33:43', '2026-06-28 18:33:43', 1, 1, 'oracle-11g-administration.pdf', 'application/pdf'),
(2, 'Introduction à l\'informatique', 'L\'informatique est la science du traitement automatique de l\'information.  Elle repose sur l\'exécution de programmes par des machines pour collecter, stocker, transformer et diffuser des données.', 'intro-info-6a415f6b7e8cd.pdf', '2026-06-28 19:52:43', '2026-06-28 19:52:43', 1, 1, 'intro info.pdf', 'application/pdf'),
(3, 'Data Warehouse et Outils Décisionnels', '- Connaître les principaux domaines d\'application des data warehouses\n- Connaître le paradigme du décisionnel (et son articulation avec le paradigme\ntransactionnel)\n- Connaître les principes, les étapes et les méthodes de la modélisation dimensionnelle\n- Savoir faire une étude de besoins\n- Savoir faire une étude des données existantes\n- Savoir faire un modèle dimensionnel en étoile\n- Savoir implémenter un data warehouse avec un SGBD relationnel\n- Savoir implémenter un processus ETL vers un data warehouse\n- Savoir interroger en SQL un data warehouse en vue d\'applications décisionnelles\n- Savoir faire un modèle dimensionnel en étoile et en locon\n- Savoir gérer les dimensions dégénérées et attributs de documentation, de segmentation et\nd\'agrégation\n- Savoir implémenter un data mart pour l\'analyse de tickets de caisse', 'data-warehouse-et-outils-decisionnels-6a415fcd668d5.pdf', '2026-06-28 19:54:21', '2026-06-28 19:54:21', 1, 1, 'data-warehouse-et-outils-decisionnels.pdf', 'application/pdf'),
(4, 'Histoire de la SUISSE', 'L\'histoire de la Suisse est marquée par la volonté d\'indépendance de communautés alpines, évoluant d\'une alliance défensive médiévale vers une neutralité armée reconnue internationalement.', 'histoiredelasuissewalter-6a417b47ee7e9.pdf', '2026-06-28 21:51:35', '2026-06-28 21:51:35', 3, 5, 'histoiredelasuissewalter.pdf', 'application/pdf'),
(5, 'Histoire de l\'ITALIE', 'L\'histoire de l\'Italie est marquée par son rôle de berceau de la civilisation romaine, suivi d\'une longue période de fragmentation politique avant son unification tardive au XIXe siècle.', 'histoire-italie-6a417b86ea85f.pdf', '2026-06-28 21:52:38', '2026-06-28 21:52:38', 3, 5, 'histoire italie.pdf', 'application/pdf'),
(6, 'La Chine depuis 1949', 'Depuis la proclamation de la République populaire de Chine le 1er octobre 1949 par Mao Zedong, l\'histoire du pays se divise en trois grandes phases : la construction du régime communiste, l\'ouverture économique et l\'affirmation d\'une superpuissance mondiale.', 'la-chine-et-le-monde-depuis-1949-le-cours-6a417c182eacd.pdf', '2026-06-28 21:55:04', '2026-06-28 21:55:04', 3, 5, 'la_chine_et_le_monde_depuis_1949_-_le_cours.pdf', 'application/pdf'),
(7, 'Résumé d\'histoire (FRANCE)', 'L\'histoire de France s\'étend sur plus de deux millénaires, marquée par la formation progressive d\'un État-nation centralisé, des révolutions politiques majeures et un rôle clé dans les conflits mondiaux.', 'histoiredefrance-6a417c87aa1b5.pdf', '2026-06-28 21:56:55', '2026-06-28 21:56:55', 3, 5, 'histoiredefrance.pdf', 'application/pdf'),
(8, 'expérimenter L’ESPACE', 'L’ESPACE ?\nL’espace est un mot qui évoque\ndeux idées différentes :\nLa première, c’est celle de la place disponible :\n« il y a beaucoup d’espace entre les arbres\ndans ce jardin ».\nLa seconde, c’est celle, plus mystérieuse,\nde ce qui peut se trouver au delà de\nl’atmosphère de la Terre, le domaine des\nsatellites, mais aussi des planètes, des étoiles,\net d’objets encore plus lointains et étranges,\nles galaxies.\nC’est cet espace là dont je vais te parler.', 'experimenter-espace-6a417fda1081f.pdf', '2026-06-28 22:11:06', '2026-06-28 22:11:06', 2, 6, 'experimenter espace.pdf', 'application/pdf'),
(9, 'Cours élémentaire d\'astronomie', 'Dans cette introduction, très brève, du cours élémentaire d\'astronomie et d\'astrophysique, nous décrivons quelques phénomènes observés, essentiellement à l\'horizon, par les premiers astronomes. Nous découvrons ainsi comment le temps, qui règle notre vie et garde la mémoire des choses passées, s\'est construit autour de ces phénomènes dont il nous faudra comprendre l\'origine.', 'Cours-Elementaire-dastronomie-6a4184bd5212f.pdf', '2026-06-28 22:31:57', '2026-06-28 22:31:57', 4, 6, 'Cours Elementaire dastronomie.pdf', 'application/pdf'),
(10, 'Voie lactée', 'La Voie lactée, aussi nommée la Galaxie (avec une majuscule), est une galaxie spirale barrée qui comprend entre 200 et 400 milliards d\'étoiles, et au moins autant de planètes. Elle abrite le Système solaire et donc la Terre. Le centre galactique est constitué d\'un trou noir supermassif, Sagittarius A*. Le diamètre de la Galaxie est estimé à 100 000 à 120 000 années-lumière, voire jusqu\'à 200 000 années-lumière, bien que le nombre d\'étoiles au-delà de 120 000 années-lumière soit très faible. Son cortège de galaxies satellites et elle font partie du Groupe local, lui-même rattaché au superamas de la Vierge, appartenant lui-même à Laniakea.', 'voie-lactee-6a41852da481e.jpg', '2026-06-28 22:33:49', '2026-06-28 22:33:49', 4, 6, 'voie lactee.jpg', 'image/jpeg'),
(11, 'L\'induction électromagnétique et les inducteurs', 'Nous avons vu dans le chapitre XI qu\'un courant produisait un champ magnétique. A la suite de cette observation, les scientifiques se sont demandé si, à l\'inverse, un champ magnétique pouvait faire apparaître un courant. Quelque 10 ans plus tard, vers 1830, Joseph Henry et Michael Faraday ont confirmé cette hypothèse, chacun de leur côté. \n\nLe terme induction électromagnétique désigne la production de courants et donc de f.é.m. à partir de champs magnétiques, on parle de courants induits et de f.é.m. induites. L\'induction électromagnétique est à l\'origine du fonctionnement des générateurs, des transformateurs et à la base de la production d\'ondes électromagnétiques telles que, par exemple, la lumière et les ondes radio.', 'L-induction-electromagnetique-et-les-inducteurs-15-6a418ab468b33.pdf', '2026-06-28 22:57:24', '2026-06-28 22:57:24', 5, 3, 'L\'induction electromagnetique et les inducteurs.15.pdf', 'application/pdf');

