INSERT INTO `user` (`id`, `name`, `email`, `image`, `born_at`, `city`, `country`, `created_at`, `about`, `roles`, `password`, `is_verified`) VALUES
(1, 'Adrien Landrieux', 'adrien_landrieux@test.fr', , '1986-06-18 00:00:00', 'Villefranche Sur Mer', 'FR', '2026-06-28 17:54:49', 'Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since 1966, when designers at Letraset and James Mosley, the librarian at St Bride Printing Library in London, took a 1914 Cicero translation and scrambled it to make dummy text for Letraset\'s Body Type sheets. It has survived not only many decades, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised thanks to these sheets and more recently with desktop publishing software like Aldus PageMaker and Microsoft Word including versions of Lorem Ipsum.', '[\"ROLE_USER\"]', '$2y$13$vjLULpqGJdlzRP5j0nqUAORTRnc9YjHO8TamPJMhuqr6/Ayc6bj4a', 1);
INSERT INTO `user` (`id`, `name`, `email`, `image`, `born_at`, `city`, `country`, `created_at`, `about`, `roles`, `password`, `is_verified`) VALUES
(2, 'ADMIN', 'admin@docshare.fr', , '1985-02-28 00:00:00', 'Andorre', 'AD', '2026-06-28 18:19:47', 'Administrateur de Plateforme Documentaire & Gestion Électronique de Documents (GED)\n\nPour me contacter: admin@docshare.fr', '[\"ROLE_ADMIN\"]', '$2y$13$LlU0Ld0F6Rw8DDVoQ2Lu7.p3urMfPSR4NiJE/.d4Piwv58aekY8aq', 1),
(3, 'Dimitri Legrand', 'dimitri.legrand@test.fr', , '1988-11-24 00:00:00', 'Montreal', 'CA', '2026-06-28 20:03:01', '🕰️ Voyageur temporel bloqué au XXIe siècle. Passionné par les coulisses de l\'Histoire, de la chute de Rome aux révolutions industrielles. Ici, je décrypte le passé pour comprendre le présent.\n\nPensez par vous même, sinon d\'autres le feront à votre place!', '[\"ROLE_USER\"]', '$2y$13$P2OUyL06XgXpkf/J6l070u8peN53grK7RHmTO3y1WrvBoel.UtEHO', 1);
INSERT INTO `user` (`id`, `name`, `email`, `image`, `born_at`, `city`, `country`, `created_at`, `about`, `roles`, `password`, `is_verified`) VALUES
(4, 'Yang Liwei', 'taikonaute@fake-program.cn', , '1965-06-21 00:00:00', 'xian de Suizhong', 'CN', '2026-06-28 22:20:53', 'né le 21 juin 1965 dans le xian de Suizhong (province du Liaoning), est le premier astronaute chinois (taïkonaute) et un major général de l\'Armée populaire de libération.  Il a rejoint l\'armée en 1983, devenant pilote de chasse avec plus de 1 350 heures de vol, avant d\'être sélectionné en 1998 pour le premier groupe d\'astronautes chinois. \n\nLe 15 octobre 2003, il a lancé la mission historique Shenzhou 5 depuis le centre de lancement de Jiuquan, devenant ainsi le troisième humain à orbiter depuis la Chine et établissant le pays comme la troisième nation à envoyer un être humain dans l\'espace de manière indépendante.  Pendant sa mission de 21 heures et 22 minutes, il a effectué 14 orbites autour de la Terre, parcourant environ 500 000 kilomètres avant d\'atterrir en Mongolie-Intérieure. \n\nAprès sa carrière spatiale, il a occupé des postes de direction clés, notamment en tant que directeur adjoint du Centre chinois de recherche et d\'entraînement des astronautes et vice-chef concepteur du programme spatial habité.  Il est marié à Zhang Yumei, qui a également travaillé dans le programme spatial chinois, et ils ont un fils.', '[\"ROLE_USER\"]', '$2y$13$yZDAKqDtomXZXAU1F/w0Xe.c94WRUQBskS4GooX86zOoppvz6xZTy', 1);
INSERT INTO `user` (`id`, `name`, `email`, `image`, `born_at`, `city`, `country`, `created_at`, `about`, `roles`, `password`, `is_verified`) VALUES
(5, 'Rick Sanchez', 'physics06@test.fr', , '1888-02-27 00:00:00', 'NICE', 'FR', '2026-06-28 22:50:33', 'Scientifique de génie et inventeur prolifique, connu pour avoir créé le pistolet-portail permettant les voyages interdimensionnels et la Courbe Finie Centrale.\n\nOriginaire de la dimension C-137', '[\"ROLE_USER\"]', '$2y$13$4YJjDJXi/KecgyQ8lj2u9uMEcDY6yRNTeSnfigzRpqPY03Z0IsUOS', 1);

